def metric(label, value, unit=''):
    return f'<div class="metric" data-tip="{label}：{value}{unit}"><div class="data-label"><i class="tiny-square"></i>{label}</div><div class="data-value number">{value}<small>{unit}</small></div></div>'

def gauge():
    return '<div class="gauge" role="img" aria-label="增长率78%"><i class="dot"></i><span class="number">78<small>%</small></span></div>'

def hexicon(kind):
    shapes = {
        'building':'<path d="M15 28V15l8-4 8 4v13M12 28h22M19 17v3m7-3v3m-7 3v3m7-3v3"/>',
        'coins':'<ellipse cx="23" cy="17" rx="7" ry="3"/><path d="M16 17v7c0 4 14 4 14 0v-7M16 21c0 4 14 4 14 0"/>',
        'chart':'<path d="M15 28V16m7 12V11m7 17V20M12 30h22"/>',
        'shield':'<path d="m23 11 9 5v8l-9 6-9-6v-8Z"/><path d="M23 16v8m-3-5 3-3 3 3"/>',
        'people':'<circle cx="20" cy="17" r="3"/><circle cx="28" cy="18" r="2"/><path d="M14 28v-4c0-5 12-5 12 0v4Zm13-6c5 0 6 2 6 5h-5"/>',
        'cube':'<path d="m23 12 9 5v10l-9 5-9-5V17Zm0 0v10m-9-5 9 5 9-5m-9 5v10"/>'
    }
    return f'<div class="hex-icon"><svg viewBox="0 0 46 46" fill="none"><path d="m23 2 18 10v22L23 44 5 34V12Z" fill="#062849" stroke="#0078ff" stroke-width="1.4"/><path d="m5 19 0-7 14-8m22 22v8l-14 8" stroke="#00c8ff" stroke-width="2"/><g stroke="#a4caff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{shapes[kind]}</g><circle cx="5" cy="34" r="1.5" fill="#00f4ca"/></svg></div>'

def tender(label,value,icon):
    return f'<div class="tender-stat" data-tip="{label}：{value}">{hexicon(icon)}<div><div class="data-label">{label}</div><div class="data-value number">{value}</div></div></div>'

